# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">THEME 2: DIGITAL LEARNING TOOLS &amp; ACADEMIC PRESENTATIONS</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">DIGITAL LEARNING &amp; RESEARCH TOOLS</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">virtual classroom:</tspan> sanal sınıf ortamı</text>\n  <text x="34" y="108" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">interactive whiteboard:</tspan> etkileşimli akıllı tahta</text>\n  <text x="34" y="128" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">reliable source:</tspan> güvenilir akademik kaynak</text>\n  <text x="34" y="148" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">digital portfolio:</tspan> dijital ürün dosyası</text>\n  <text x="34" y="168" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">peer feedback:</tspan> akran geri bildirimi</text>\n  <text x="34" y="188" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">self-assessment:</tspan> öz değerlendirme</text>\n  <text x="34" y="206" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">collaborative project:</tspan> iş birlikli çalışma</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">ACADEMIC PRESENTATION PHRASES</text>\n  <text x="370" y="88" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Opening:</tspan> "Today I am going to talk about..."</text>\n  <text x="370" y="108" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Structuring:</tspan> "First of all / To begin with..."</text>\n  <text x="370" y="128" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Adding:</tspan> "Moreover / Furthermore / In addition..."</text>\n  <text x="370" y="148" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Visuals:</tspan> "As you can see on this chart/slide..."</text>\n  <text x="370" y="168" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Concluding:</tspan> "To sum up / In conclusion..."</text>\n  <text x="370" y="188" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Q&amp;A:</tspan> "Do you have any questions?"</text>\n  <text x="370" y="206" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">eye contact &amp; body language:</tspan> göz teması ve beden dili</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Effective presentations combine reliable information, clear signposting phrases and visual aids.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">EXPRESSING LEARNING PREFERENCES: PREFER vs. WOULD RATHER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">PREFER (GENEL TERCİHLER)</text>\n  <text x="34" y="88" font-size="11" font-weight="bold" fill="#7e22ce">1. prefer + Noun + to + Noun</text>\n  <text x="44" y="106" font-size="10.5" fill="#581c87">"I prefer printed books to e-books."</text>\n  <text x="34" y="130" font-size="11" font-weight="bold" fill="#7e22ce">2. prefer + V-ing + to + V-ing</text>\n  <text x="44" y="148" font-size="10.5" fill="#581c87">"She prefers studying in the library to studying at home."</text>\n  <text x="34" y="172" font-size="11" font-weight="bold" fill="#7e22ce">3. prefer + to V1 + rather than + V1</text>\n  <text x="44" y="190" font-size="10.5" fill="#581c87">"We prefer to take notes rather than record audio."</text>\n  <text x="34" y="208" font-size="10.5" font-weight="bold" fill="#6b21a8">Dikkat: \'prefer\' yapısında karşılaştırma edatı \'to\' olur!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">WOULD RATHER (\'D RATHER — BELİRLİ TERCİH)</text>\n  <text x="370" y="88" font-size="11" font-weight="bold" fill="#c2410c">1. would rather + V1 (Yalın Fiil)</text>\n  <text x="380" y="106" font-size="10.5" fill="#7c2d12">"I would rather revise with flashcards tonight."</text>\n  <text x="370" y="130" font-size="11" font-weight="bold" fill="#c2410c">2. would rather + V1 + than + V1</text>\n  <text x="380" y="148" font-size="10.5" fill="#7c2d12">"He\'d rather join the coding club than play chess."</text>\n  <text x="370" y="172" font-size="11" font-weight="bold" fill="#c2410c">3. Olumsuz: would rather + NOT + V1</text>\n  <text x="380" y="190" font-size="10.5" fill="#7c2d12">"They would rather not postpone the presentation."</text>\n  <text x="370" y="208" font-size="10.5" font-weight="bold" fill="#9a3412">Dikkat: \'would rather\' sonrasında fiil daima V1 (yalın) gelir!</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">prefer + V-ing + TO + V-ing  &lt;===&gt;  would rather + V1 + THAN + V1</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">THEME 2 REVISION: FUTURE FORMS, MODALS &amp; LINKING WORDS</text>\n  <rect x="20" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">FUTURE PLANS &amp; PREDICTIONS</text>\n  <text x="30" y="88" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">be going to + V1:</tspan></text>\n  <text x="36" y="104" font-size="10" fill="#1e3a8a">Prior plan / clear evidence</text>\n  <text x="30" y="126" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">will + V1:</tspan></text>\n  <text x="36" y="142" font-size="10" fill="#1e3a8a">Instant decision / promise</text>\n  <text x="36" y="158" font-size="10" fill="#1e3a8a">(I think, I hope, probably)</text>\n  <text x="30" y="180" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Present Continuous:</tspan></text>\n  <text x="36" y="196" font-size="10" fill="#1e3a8a">Fixed arrangements</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">MODALS IN CLASSROOM</text>\n  <text x="255" y="88" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">should / ought to:</tspan> Advice</text>\n  <text x="255" y="110" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">must:</tspan> Inner obligation / rule</text>\n  <text x="255" y="132" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">have to:</tspan> External rule</text>\n  <text x="255" y="154" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">mustn\'t:</tspan> Prohibition (Yasak)</text>\n  <text x="255" y="176" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">don\'t have to / needn\'t:</tspan></text>\n  <text x="261" y="192" font-size="10" fill="#7f1d1d">Lack of necessity</text>\n  <rect x="470" y="42" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">PURPOSE &amp; REASON LINKERS</text>\n  <text x="480" y="88" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">in order to / so as to + V1:</tspan></text>\n  <text x="486" y="104" font-size="10" fill="#14532d">"-mek / -mak amacıyla"</text>\n  <text x="480" y="126" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">so that + S + can/will + V1:</tspan></text>\n  <text x="486" y="142" font-size="10" fill="#14532d">"-sın diye / -ebilsin diye"</text>\n  <text x="480" y="164" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">because / since / as + Clause</tspan></text>\n  <text x="480" y="186" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">therefore / as a result:</tspan></text>\n  <text x="486" y="202" font-size="10" fill="#14532d">Sonuç bildiren bağlaçlar</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Theme 2 integrates study strategies, future goals, preferences and modal verbs in academic contexts.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
